EXTRAS = [
dict(n=1, gr='greet', vb='go,say,meet,see,come',
 c1="Hello, hi ou hey?|Hello é neutro e serve para qualquer pessoa. Hi é mais casual e Hey é para amigos. Em Londres e Nova York, os vizinhos dizem 'Morning!' em vez de 'Good morning!'.",
 c2="Como você está? Ninguém conta a vida!|Em inglês, 'How are you?' costuma ser só um cumprimento. Quem pergunta espera ouvir algo curto como 'Fine, thanks!'. Responder com uma longa história surpreende os americanos.",
 ar=("A morning on Maple Street","Maple Street wakes up at seven. Mia opens her window and says, \"Good morning!\" to the street. Omar the baker waves from the shop. A boy on a bike says, \"Hi!\" and rings his bell. Mrs. Brown walks her dog and says, \"Lovely day, isn't it?\" In the afternoon, people say, \"Good afternoon.\" At night, they say, \"Good night!\" On this street, everybody says hello. It is a small word, but it makes friends.","Pela manhã, a rua inteira se cumprimenta; uma palavra simples faz amigos.","Quem abre a janela?=Mia|Omar|The boy;;O que as pessoas dizem à noite?=Good night!|Good morning!|Goodbye!"),
 ex="What's up?=E aí?~Entre amigos, bem informal|Nice to see you!=Que bom ver você!~Ao encontrar alguém|Take care!=Se cuide!~Ao se despedir|See you around!=A gente se vê!~Despedida casual|Long time no see!=Quanto tempo!~Reencontro",
 tf="Good night é usado para dizer olá à noite.=F|Hi é mais informal que Hello.=T|Em inglês, How are you? quase sempre pede uma resposta longa.=F|Good afternoon é usado depois do meio-dia.=T",
 odd="hello,hi,goodbye,hey=goodbye|morning,afternoon,evening,table=table"),
dict(n=2, gr='name', vb='be,call,meet,spell,know',
 c1="Nomes e sobrenomes|Em inglês, o primeiro nome é 'first name' e o sobrenome é 'last name' ou 'surname'. Em formulários, o campo 'Given name' é o primeiro nome. E 'nickname' é o apelido: Elizabeth pode ser Liz, Beth ou Betty.",
 c2="Apelidos que viram nome|William vira Bill, Robert vira Bob e Margaret vira Maggie. Muitos apelidos em inglês vieram de rimas antigas: Robert → Rob → Bob. Pergunte 'What do you like to be called?' para ser educado.",
 ar=("Class one","Today is the first day of class. Mia, the teacher, stands in front of the board. She writes her name: M-I-A. Then she asks every student, \"What's your name?\" Ana says, \"My name is Ana.\" Tom says, \"I'm Tom. Nice to meet you!\" A shy girl whispers, \"I'm Lily.\" Mia smiles. \"Nice to meet you, Lily. Don't be shy. We are friends here.\" By the end of the class, everybody knows everybody's name.","No primeiro dia de aula, cada aluno diz o nome e a turma vira amiga.","Quem é a professora?=Mia|Ana|Lily;;Quem sussurra o nome?=Lily|Tom|Ana"),
 ex="Nice to meet you.=Prazer em conhecer você.~Primeira vez que você vê alguém|Call me Tom.=Pode me chamar de Tom.~Apresentação informal|Pleased to meet you.=Muito prazer.~Mais formal|How do you pronounce it?=Como se pronuncia?~Nome difícil|It's a pleasure.=É um prazer.~Formal",
 tf="'I'm Tom' é a forma curta de 'I am Tom'.=T|Last name é o primeiro nome.=F|Em inglês, a pergunta What's your name? usa what is.=T|Pleased to meet you é muito informal.=F",
 odd="Ana,Tom,Lily,teacher=teacher|name,surname,nickname,apple=apple"),
dict(n=3, gr='from', vb='be,live,come,speak,visit',
 c1="Países e nacionalidades|Em inglês, nome de país e de nacionalidade têm iniciais maiúsculas: Brazil / Brazilian, Japan / Japanese, Egypt / Egyptian. Muitas terminam em -an, -ian, -ese ou -ish.",
 c2="Uma língua, muitos sotaques|Mais de 1,5 bilhão de pessoas falam inglês no mundo, mas poucas têm o mesmo sotaque! Americanos, britânicos, indianos e australianos têm jeitos bem diferentes de falar. O importante é se fazer entender.",
 ar=("Four friends, four countries","On Maple Street, four friends have four different homes. Mia is from Brazil. Ken is from Japan. Sara is from Egypt. Tom is from England. They all live in the same street now. Mia speaks Portuguese, Ken speaks Japanese and Sara speaks Arabic, but they talk to each other in English. \"Where are you from?\" is the first question they ask every new neighbor. And every new neighbor answers with a big smile.","Quatro amigos de países diferentes usam o inglês para conversar.","Qual idioma eles usam juntos?=English|Japanese|Arabic;;De onde Sara é?=Egypt|Japan|England"),
 ex="I'm originally from...=Sou originalmente de...~Quando você se mudou de lugar|I grew up in...=Cresci em...~Falando da infância|Where are you based?=Onde você mora/trabalha?~Mais formal|It's a small world!=O mundo é pequeno!~Coincidência|Welcome to town!=Bem-vindo à cidade!~Receber alguém",
 tf="I'm from Brazil significa Eu sou do Brasil.=T|Brazilian é o nome do país.=F|She's from Egypt significa Ela é do Egito.=T|Em inglês, nacionalidades se escrevem com letra minúscula.=F",
 odd="Brazil,Japan,Egypt,apple=apple|speak,live,visit,table=table"),
dict(n=4, gr='numbers', vb='count,have,buy,sell,want',
 c1="Dúzia, centena, milhar|Em inglês, 'a dozen' é uma dúzia (12), 'a hundred' é cem e 'a thousand' é mil. Nos EUA, 'a billion' tem 9 zeros. Telefones se leem dígito a dígito: 5-5-5, 0-1-2-3.",
 c2="O número da sorte|Nos países de língua inglesa, o 13 é considerado azarado, e muitos prédios não têm um 13º andar! Já o 7 é visto como número da sorte. E em inglês, 'zero' também pode ser 'oh' ao falar telefone.",
 ar=("At Leo's stall","Leo has a small stall at the Maple Street market. He sells apples, oranges and bananas. Every morning he counts his fruit: ten red apples, twelve yellow bananas and fifteen oranges. A girl comes at nine o'clock and asks, \"How many apples are there?\" Leo laughs and says, \"There are ten, but today I have a special price.\" The girl buys six apples and eight oranges. Leo counts the money: one, two, three... fourteen dollars! \"Thank you!\" says the girl.","Leo conta suas frutas e vende uma parte para uma menina, contando em inglês.","Quantas maçãs Leo tem?=Ten|Twelve|Fifteen;;Quanto a menina paga?=Fourteen dollars|Ten dollars|Six dollars"),
 ex="Count me in!=Pode contar comigo!~Aceitar participar|A couple of...=Algumas / uns dois~Informal|Hundreds of...=Centenas de...~Quantidade grande|Number one!=O melhor!~Elogio|Two heads are better than one.=Duas cabeças pensam melhor.~Provérbio",
 tf="Thirteen e thirty são palavras iguais.=F|A dozen é uma dúzia.=T|How many serve com palavras no plural.=T|No inglês, one hundred é 1.000.=F",
 odd="one,two,three,apple=apple|ten,twenty,fifty,blue=blue"),
dict(n=5, gr='spell', vb='spell,write,repeat,say,read',
 c1="Por que o inglês é tão difícil de soletrar?|Em inglês, a mesma letra pode ter sons diferentes: 'ough' soa diferente em through, though e tough! Isso aconteceu porque a escrita foi fixada séculos atrás, enquanto a pronúncia continuou mudando.",
 c2="Spelling bee|Nos EUA há um concurso famoso chamado 'spelling bee', em que crianças soletram palavras difíceis em voz alta. Os campeões aparecem na TV! O segredo é conhecer as letras pelo nome em inglês.",
 ar=("A library card","Hana goes to the library on Monday. She wants a card. The librarian, Emma, asks, \"What's your name?\" \"Hana,\" she says. \"How do you spell it?\" \"H-A-N-A.\" Emma writes it down. \"And your last name?\" \"Kim. K-I-M.\" Emma asks for an email too. Hana says, \"hana dot kim at mail dot com.\" Emma gives her a blue card with her name on it. Now Hana can borrow three books. She chooses a book about animals and smiles.","Hana faz o cartão da biblioteca soletrando nome e e-mail.","Como Hana soletra o nome?=H-A-N-A|H-A-N-N-A|A-N-A;;Quantos livros ela pode pegar?=Three|Five|Ten"),
 ex="Could you spell that?=Pode soletrar?~Pedir a grafia|Could you repeat that?=Pode repetir?~Não ouviu bem|Is that with one N or two?=É com um N ou dois?~Conferir letras|With a K, like kite.=Com K, de kite.~Esclarecer letras|That's right.=Isso mesmo.~Confirmar",
 tf="A letra A em inglês se diz 'êi'.=T|At é a palavra para o ponto (.) em e-mails.=F|How do you spell it? pede a grafia de uma palavra.=T|Todas as letras soam igual em inglês.=F",
 odd="A,B,C,hello=hello|email,at,dot,banana=banana"),
dict(n=6, gr='polite', vb='thank,say,help,order,eat',
 c1="O poder do 'please'|Pesquisas mostram que pedidos com 'please' têm muito mais chance de serem atendidos. Em inglês, ele aparece até em pedidos pequenos: 'Pass the salt, please'. Sem 'please', o pedido soa seco.",
 c2="Sorry, pardon ou excuse me?|Sorry é para pedir desculpas. Excuse me é para chamar atenção ou passar por alguém. Pardon? (ou Sorry?) é para pedir que repitam. Os britânicos dizem 'sorry' até quando alguém pisa no pé deles!",
 ar=("The bakery on the corner","Omar's bakery opens at six. At seven there is a line outside. A woman says, \"Good morning! A coffee and a bread roll, please.\" Omar answers, \"Here you are.\" \"Thank you very much!\" \"You're welcome!\" A boy bumps into a man. \"Oh, sorry!\" says the boy. \"No problem,\" says the man. Omar smiles. In his bakery, people always say please, thank you and sorry. \"Politeness is free,\" he says, \"but it makes everything better.\"","Na padaria de Omar, a cortesia faz todo mundo se dar bem.","O que a mulher pede?=A coffee and bread|Cake|Water;;O que o menino diz?=Sorry!|Goodbye!|Hello!"),
 ex="After you.=Depois de você.~Deixar alguém passar primeiro|Thanks a million!=Muitíssimo obrigado!~Informal|My pleasure.=É um prazer ajudar.~Resposta a thanks|Pardon me?=Como disse?~Não entendeu|Bless you!=Saúde!~Quando alguém espirra",
 tf="Please deve ir no fim de muitos pedidos.=T|You're welcome é o que se diz depois de pedir desculpas.=F|Excuse me serve para passar por alguém.=T|Sorry nunca é usado em inglês.=F",
 odd="please,thanks,sorry,bread=bread|coffee,water,tea,excuse=excuse"),
dict(n=7, gr='thisthat', vb='have,use,open,close,write',
 c1="This e that no mundo real|Se você estiver segurando um objeto, use 'this'. Se estiver apontando para algo distante, use 'that'. Ao telefone, os ingleses perguntam: 'Who's that?' (Quem é?), e os americanos 'Who's this?'.",
 c2="Objetos de sala de aula|Em escolas de língua inglesa, os alunos têm 'pencil cases' (estojos), 'binders' (fichários) e 'notebooks' (cadernos). E 'rubber' é borracha no Reino Unido, mas nos EUA se diz 'eraser'. Cuidado: 'rubber' nos EUA tem outro sentido!",
 ar=("A new classroom","Mia's classroom is on the first floor. There is a big board on the wall and a clock above the door. There are twelve desks, twelve chairs and four windows. On Mia's desk there are books, pens and pencils. \"What's this?\" asks a student, pointing at a small box. \"It's a pencil case,\" says Mia. \"And what's that?\" asks another student, pointing at the clock. \"That's a clock,\" Mia answers. \"It's nine o'clock. Time for class!\" The students sit down and open their notebooks.","Mia mostra os objetos da sala e os alunos perguntam o nome de cada um.","O que há acima da porta?=A clock|A board|A window;;Que horas são?=Nine o'clock|Ten o'clock|Noon"),
 ex="What do you call this?=Como se chama isto?~Pedir uma palavra|It's called a...=Chama-se...~Explicar nomes|I don't know what it's called.=Não sei como se chama.~Palavra esquecida|It's over there.=Está ali.~Apontar longe|Here you go.=Aqui está.~Entregar algo",
 tf="This is usado para coisas perto.=T|These são o plural de that.=F|An é usado antes de som de vogal.=T|Those são para coisas perto.=F",
 odd="pen,pencil,book,window=window|this,that,these,chair=chair"),
dict(n=8, gr='adj', vb='like,love,paint,choose,see',
 c1="Cores que dão nome a emoções|Em inglês, 'feeling blue' é estar triste, 'green with envy' é estar com inveja e 'seeing red' é ficar furioso. As cores também aparecem em expressões como 'a white lie' (mentira inocente).",
 c2="A cor mais popular do mundo|Em pesquisas de vários países, o azul é a cor favorita mais citada. O vermelho é associado a paixão e perigo; o verde à natureza e à sorte na Irlanda. Cada cultura dá significados diferentes às cores.",
 ar=("Rosa's toy shop","Rosa has a toy shop with colorful things. In the window there is a red car, a blue ball and a green frog. On the shelf there is a yellow duck, a white rabbit and a black cat. A boy named Ben comes in with his mother. \"What's your favorite color?\" asks Rosa. \"Blue!\" says Ben. Rosa gives him the blue ball. \"It's a present,\" she says. Ben is very happy. Now he has a blue ball and a big smile.","Na loja de brinquedos de Rosa, Ben ganha uma bola azul, sua cor favorita.","Qual é a cor do sapo?=Green|Red|Yellow;;O que Rosa dá a Ben?=A blue ball|A red car|A cat"),
 ex="Black and white=Preto e branco~Também: claro e simples|Out of the blue=Do nada~Algo inesperado|Feeling blue=Estar triste~Idiom|Green with envy=Roxo de inveja~Idiom|Red tape=Burocracia~Idiom",
 tf="A cor vem antes do substantivo em inglês.=T|Red é a cor azul.=F|My favorite color is… é uma frase para dizer a cor preferida.=T|Pink é a cor do céu.=F",
 odd="red,blue,green,table=table|black,white,brown,chair=chair"),
dict(n=9, gr='poss', vb='have,live,love,help,visit',
 c1="Famílias grandes e pequenas|Em inglês há uma palavra para quase tudo: 'siblings' são irmãos e irmãs, 'in-laws' são parentes por casamento e 'grandparents' são avós. Já 'cousin' vale para primo e prima.",
 c2="Quem é quem em inglês|'My other half' é o marido ou a esposa; 'my partner' é o(a) parceiro(a). 'Aunt' é tia e 'uncle' é tio, mas 'auntie' e 'uncle' também são usados com carinho para amigos próximos da família.",
 ar=("The photo on the wall","On the wall of Sara's living room there is a big family photo. In the middle there are her grandmother and grandfather. They are smiling. Next to them are her mother and father. Her mother's name is Nadia and her father's name is Karim. In front there are Sara, her brother and her two sisters. \"This is my family,\" says Sara to a visitor. \"It's a big family, but we are very close.\" The visitor smiles and says, \"What a beautiful photo!\"","Sara apresenta a foto da família grande e unida.","Quem está no meio da foto?=Grandparents|Parents|Brothers;;Qual é o nome do pai?=Karim|Nadia|Sara"),
 ex="We're a close family.=Somos uma família unida.~Falar da relação|It runs in the family.=É de família.~Característica herdada|Like father, like son.=Tal pai, tal filho.~Provérbio|Black sheep of the family=Ovelha negra~Idiom|Blood is thicker than water.=Família em primeiro lugar.~Provérbio",
 tf="His e her são possessivos.=T|Brother é irmã.=F|Parents são pai e mãe.=T|Cousin só serve para primo homem.=F",
 odd="mother,father,sister,table=table|brother,uncle,aunt,chair=chair"),
dict(n=10, gr='greet', vb='meet,say,be,live,have',
 c1="Festas de rua pelo mundo|As 'block parties' dos EUA fecham a rua para vizinhos comerem e dançarem. No Reino Unido há as 'street parties' em ocasiões especiais. É uma ótima forma de conhecer gente nova e praticar inglês.",
 c2="O poder do 'small talk'|Falar sobre o clima, a comida ou a rua é a base do 'small talk', a conversa leve que abre portas em inglês. Funciona porque mostra interesse sem ser invasivo. Comece com 'Nice weather today, isn't it?'.",
 ar=("The Maple Street party","Today is a big day on Maple Street. There is a party in the middle of the street. Mia brings a cake. Ken brings rice and fish. Sara brings fruit and juice. Tom plays music. A small boy asks, \"Where are you from?\" to every person. He hears Brazil, Japan, Egypt and England. \"Wow, so many countries!\" he says. At night everybody says \"Good night!\" and \"See you next week!\" Nobody wants to go home.","Uma festa na rua reúne vizinhos de quatro países.","Quem traz música?=Tom|Mia|Ken;;O que as pessoas dizem à noite?=Good night!|Good morning!|Hello!"),
 ex="Nice weather, isn't it?=Que tempo bom, não é?~Abrir conversa|How's it going?=Como vai?~Informal|Make yourself at home.=Fique à vontade.~Receber alguém|Help yourself!=Sirva-se!~Oferecer comida|Let's keep in touch.=Vamos manter contato.~Despedida",
 tf="A festa é no meio da rua.=T|Tom traz o bolo.=F|Small talk é uma conversa leve.=T|Todos vão embora cedo.=F",
 odd="cake,rice,fruit,music=music|party,street,friend,Brazil=Brazil"),
]
